import test from 'node:test';import assert from 'node:assert/strict';import {EventEmitter} from 'node:events';import {mkdtemp,readFile,readdir} from 'node:fs/promises';import {join,resolve} from 'node:path';import {tmpdir} from 'node:os';
import {observedResidentSource} from './resident-backend.mjs';import {observeOwnedServer} from './resident-server-timing.mjs';
test('resident hook preserves the actual original budgets, scheduling and game assertions',async()=>{const original=await readFile(resolve('island/tests/v213-task-chain-browser.mjs'),'utf8'),source=observedResidentSource(original,'file:///owned-observer.mjs');for(const needle of ["createWorkTimeBudget(120000,'First job')","createWorkTimeBudget(240000,'Remaining chain')",'deadlineMs:1980000','assert(firstBudget.usedMs<=120000)','assert(remainingBudget.usedMs<=240000)','assert.equal(receipts.length,3)'])assert(source.includes(needle),needle);assert.equal(source.match(/await observeOwnedServer\(service,out\)/g).length,1);assert.equal(source.match(/await backendObservation.finish\(\)/g).length,1);});
test('an incompatible original fixture fails instead of silently omitting observation',()=>{assert.throws(()=>observedResidentSource('different source','file:///owned.mjs'));});
test('observer preserves request body handling,input identity,result identity and original listeners',async()=>{
 const out=await mkdtemp(join(tmpdir(),'hd-backend-observation-')),server=new EventEmitter(),canary='PRIVATE_BODY_CANARY_DO_NOT_LOG';let accepted,receivedBody,originalCalls=0;
 const input={kind:'resident',operation:'finish',requestId:'owned-known-job',actorId:5,prompt:canary},result={receipt:{outcome:'finished'},state:{private:canary}};const action=async function(theme,body){assert.equal(this,store);assert.equal(theme,'pixel');assert.equal(body,input);return result;},store={action},get=async()=>({saves:store}),service={server,tenants:{get}};
 const complete=new Promise(resolve=>accepted=resolve),original=async function(req,res){originalCalls++;assert.equal(req.listenerCount('data'),0);const tenant=await service.tenants.get('owned-fictional-token');assert.equal(await tenant.saves.action('pixel',input),result);res.end(canary);accepted();};server.on('request',original);
 const observer=await observeOwnedServer(service,out,{liveIntervalMs:20,profileChunkMs:40}),req=new EventEmitter();Object.assign(req,{url:'/api/saves/pixel/action?token='+canary,method:'POST'});const res=new EventEmitter();Object.assign(res,{statusCode:200,writableFinished:false,end(body){receivedBody=body;this.writableFinished=true;this.emit('finish');this.emit('close');return this;}});
 server.emit('request',req,res);await complete;await new Promise(resolve=>setTimeout(resolve,100));const first=observer.finish(),second=observer.finish();assert.equal(first,second);await first;
 assert.equal(originalCalls,1);assert.equal(receivedBody,canary);assert.equal(store.action,action);assert.equal(service.tenants.get,get);assert.deepEqual(server.listeners('request'),[original]);const record=JSON.parse(await readFile(join(out,'backend-observation.json'),'utf8'));assert.equal(record.http.length,1);assert.equal(record.http[0].path,'/api/saves/pixel/action');assert.equal(record.calls[0].outcome,'finished');assert.equal(record.calls[0].input.requestId,input.requestId);assert(!JSON.stringify(record).includes(canary));assert(record.profiles.length>=1);assert((await readdir(out)).includes('backend-progress.json'));assert.deepEqual(record.errors,[]);
});
test('observer preserves original thrown errors while omitting their private messages',async()=>{
 const out=await mkdtemp(join(tmpdir(),'hd-backend-error-')),server=new EventEmitter(),error=Object.assign(Error('PRIVATE_ERROR_CANARY'),{code:'save_busy',status:503}),action=async()=>{throw error;},store={action},get=async()=>({saves:store}),service={server,tenants:{get}};server.on('request',()=>{});
 const observer=await observeOwnedServer(service,out,{liveIntervalMs:1000,profileChunkMs:1000});const tenant=await service.tenants.get('owned');await assert.rejects(tenant.saves.action('pixel',{kind:'resident',operation:'finish',requestId:'owned-job'}),e=>e===error);await observer.finish();const record=JSON.parse(await readFile(join(out,'backend-observation.json'),'utf8'));assert.equal(record.calls[0].error.code,'save_busy');assert(!JSON.stringify(record).includes('PRIVATE_ERROR_CANARY'));assert.equal(store.action,action);assert.deepEqual(record.errors,[]);
});
